package daret_digital.com;

import daret_digital.com.domain.DaretGroup;
import daret_digital.com.domain.GroupMembership;
import daret_digital.com.domain.GroupRole;
import daret_digital.com.domain.Payment;
import daret_digital.com.domain.PaymentStatus;
import daret_digital.com.domain.User;
import org.springframework.test.util.ReflectionTestUtils;

import java.math.BigDecimal;
import java.util.UUID;

/**
 * Small factory methods to build entities for tests.
 *
 * Why this exists: ids are normally generated by the database when an entity is saved.
 * In a unit test there is no database, so we set the "id" field ourselves with
 * ReflectionTestUtils (it writes a private field without needing a setter).
 * If your id field is not called "id", change the name here, in one place.
 */
public final class TestData {

    private TestData() {}

    public static User aUser(String email) {
        User user = new User();
        user.setEmail(email);
        user.setFirstname("Test");
        user.setLastname("User");
        user.setPassword("hashed-password");
        ReflectionTestUtils.setField(user, "id", UUID.randomUUID());
        return user;
    }

    public static DaretGroup aGroup(int members, String montant, DaretGroup.DaretStatus status) {
        DaretGroup group = new DaretGroup();
        group.setNom("Test daret");
        group.setMontant(new BigDecimal(montant));
        group.setNombreMembres(members);
        group.setStatut(status);
        group.setTourActuel(0);
        ReflectionTestUtils.setField(group, "id", UUID.randomUUID());
        return group;
    }

    public static GroupMembership aMembership(DaretGroup group, User user, GroupRole role, Integer position) {
        GroupMembership membership = new GroupMembership();
        membership.setGroup(group);
        membership.setUser(user);
        membership.setRole(role);
        membership.setPosition(position);
        return membership;
    }

    public static Payment aPayment(DaretGroup group, User member, int cycle, PaymentStatus status) {
        Payment payment = new Payment(group, member, cycle, group.getMontant());
        payment.setStatus(status);
        ReflectionTestUtils.setField(payment, "id", UUID.randomUUID());
        return payment;
    }
}